import 'package:flutter/material.dart';
class DashboardStatCard extends StatelessWidget { const DashboardStatCard({required this.title, required this.value, required this.icon, this.subtitle, super.key}); final String title; final String value; final String? subtitle; final IconData icon; @override Widget build(BuildContext context) => Card(child: Padding(padding: const EdgeInsets.all(16), child: Row(children: [Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text(title, style: const TextStyle(color: Colors.grey)), Text(value, style: Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight: FontWeight.bold)), if (subtitle != null) Text(subtitle!, style: const TextStyle(fontSize: 12, color: Colors.grey))])), CircleAvatar(child: Icon(icon))]))); }
